@Entity
class Customer {
    @Id @GeneratedValue
    private Long id;

    @OneToMany(mappedBy = "customer", cascade = CascadeType.ALL,
               orphanRemoval = true)
    private List<PurchaseOrder> orders = new ArrayList<>();

    public void addOrder(PurchaseOrder order) {
        orders.add(order);
        order.setCustomer(this);
    }
}

